using System;using System.Collections;using UnityEngine;using UnityEngine.SceneManagement;using Mirror;using MultiFPS;using MultiFPS.UI;using MultiFPS.Gameplay.Gamemodes;using ROM.Progression;using ROM.UI.Sprint01;
namespace ROM.Tutorial.Crilium {
[Serializable]public sealed class CriliumCheckpoint {public int Version=1,Lesson;public string Journal;public bool FragmentFallen;}
// Only the existing local character record stores prologue status; normal journal remains separate.
public static class CriliumSession {
 public const string SceneName="Crilium",ScenePath="Assets/ROM/Tutorial/Crilium/Crilium.unity",RiftScene="Assets/ROM/Levels/map_rom_horde.unity";
 static LocalCharacterRoster roster;static string characterId;static bool crossing;
 public static bool Active=>SceneManager.GetActiveScene().name==SceneName;
 public static string ObjectiveText(string id){if(!Active)return null;var definition=CriliumDefinition.Load;if(!definition||id!=definition.QuestId)return null;var director=UnityEngine.Object.FindFirstObjectByType<CriliumDirector>();return director?director.CurrentObjectiveText:null;}
 public static bool CanOfferQuest(string id){if(!Active)return true;var definition=CriliumDefinition.Load;if(!definition||id!=definition.QuestId)return true;var director=UnityEngine.Object.FindFirstObjectByType<CriliumDirector>();return director&&director.Current!=CriliumLesson.Movement&&director.Current!=CriliumLesson.Camera;}
 public static CriliumCheckpoint Resume {get{var c=roster?.Active;if(c==null||c.Id!=characterId||c.CreliumCompleted||string.IsNullOrEmpty(c.CreliumResume)||c.CreliumResume.Length>65536)return null;try{var value=JsonUtility.FromJson<CriliumCheckpoint>(c.CreliumResume);return value!=null&&value.Version==1?value:null;}catch{return null;}}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Install(){roster=null;characterId=null;crossing=false;SceneManager.sceneLoaded-=Loaded;SceneManager.sceneLoaded+=Loaded;}
 static void Loaded(Scene scene,LoadSceneMode mode){if(mode!=LoadSceneMode.Single)return;RiftJournalView.ClearTransientView();RiftBagLayout.ClearCriliumLayout();foreach(var j in UnityEngine.Object.FindObjectsByType<RiftJournalPlayer>(FindObjectsSortMode.None))j.ResetCriliumJournal();if(crossing&&scene.path==RiftScene&&DNNetworkManager.Instance)DNNetworkManager.Instance.StartCoroutine(ConfirmArrival());}
 static IEnumerator ConfirmArrival(){float began=Time.realtimeSinceStartup;while(crossing&&Time.realtimeSinceStartup-began<30){if(!NetworkClient.active)yield break;var p=ClientFrontend.ClientPlayerInstance;if(SceneManager.GetActiveScene().path==RiftScene&&p&&p.MyCharacter&&p.MyCharacter.Health.CurrentHealth>0&&p.PlayerInfo.CharacterId==characterId){try{if(roster!=null)roster.SaveCrelium(characterId,"",true);}catch{Debug.LogWarning("Crelium completion could not be saved; retry remains available.");}crossing=false;yield break;}yield return null;}}
 public static bool SaveCheckpoint(int lesson,JournalState state,bool fallen){if(!Active||roster==null||state==null||state.CharacterId!=characterId||crossing)return false;var value=new CriliumCheckpoint{Lesson=lesson,Journal=JsonUtility.ToJson(state),FragmentFallen=fallen};var json=JsonUtility.ToJson(value);if(json.Length>65536)return false;try{return roster.SaveCrelium(characterId,json,false);}catch{Debug.LogWarning("Crelium checkpoint could not be saved.");return false;}}
 public static void BeginCrossing(){if(Active&&roster!=null)crossing=true;}
 public static void Enter(LocalCharacterRoster localRoster=null){if(NetworkClient.active||NetworkServer.active)return;var c=localRoster?.Active;if(c==null||c.ClassKey!="warrior"||c.CreliumCompleted){RiftVillageUI.Notify("Este personaje ya completó Crelium.");return;}var manager=DNNetworkManager.Instance;if(!manager)return;roster=localRoster;characterId=c.Id;crossing=false;RoomSetup.Properties.P_Gamemode=Gamemodes.Raid;RoomSetup.Properties.P_MaxPlayers=1;RoomSetup.Properties.P_FillEmptySlotsWithBots=false;RoomSetup.Properties.P_GameDuration=999999;RoomSetup.Properties.P_RespawnCooldown=3;manager.maxConnections=1;manager.onlineScene=ScenePath;manager.StartHost();}
}}
